mapper.select:
SELECT a.emp_id, e.emp_name, d.dep_name AS department_name, a.work_date AS late_date,
       TIMESTAMPDIFF(MINUTE, a.check_in_time, '09:00:00') AS late_duration,
       a.late_reason, a.status
FROM attendance a
JOIN employee e ON a.emp_id = e.emp_id
JOIN department d ON e.dep_id = d.dep_id
WHERE a.check_in_time > '09:00:00'
AND a.work_date BETWEEN #{startDate} AND #{endDate}

    AND a.emp_id = #{empId}


    AND e.dep_id = #{depId}

SELECT a.emp_id, e.emp_name, d.dep_name AS department_name, a.work_date, 
       a.work_type, a.absence_reason AS reason
FROM attendance a
JOIN employee e ON a.emp_id = e.emp_id
JOIN department d ON e.dep_id = d.dep_id
WHERE a.work_date BETWEEN #{startDate} AND #{endDate}

    AND a.emp_id = #{empId}


    AND e.dep_id = #{depId}

